"""Prioritize same-radius branches with explicitly missing new supports."""
from pathlib import Path
from fractions import Fraction as F
from math import isqrt
import json,hashlib
R=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 source=R/'verify/out/n100-lower-radius-bottleneck-firstpass.json';z=json.loads(source.read_text(encoding='utf-8'));target=next(r for r in z['radius_samples'] if F(r['radius'])==F(11324,100000));assert target['n99_exclusion']['status']=='PASS' and target['m100_surviving_B']==list(range(31,40));b31=all(t['area_positive'] and t['ear_sign_pass'] and t['bad_sign_pass'] for t in target['B31_fixed_rows']) and F(target['B31_degree_window_margin_lower'])>0 and target['B31_fan']['status']=='PASS';assert b31
 # The old fixed tail coefficients alone impose r^2 < constant/coefficient.
 p=R/'runtime/disk100-release-lf-67ebf1c/certified_bounds_11323/working/lower_bounds_extension_20261004/verify_extension.py';import sys;sys.path.insert(0,str(p.parent));import verify_extension as g
 mu=F(92531,10**7);intercept=F(751,100000);K=F(3892,12500);coefficient=(198-36)*g.AH+36*K;threshold=((1-mu)*g.PL-36*intercept)/coefficient;scale=10**15;lo=isqrt(threshold.numerator*scale*scale//threshold.denominator);assert F(lo,scale)**2<=threshold<F(lo+1,scale)**2;cap=((1-mu)*g.PL-coefficient*F(11324,100000)**2)/36
 trial=R/'verify/out/n100-tail-new-radius-trial-139.json';t=json.loads(trial.read_text(encoding='utf-8'));assert t['visited']==250000 and t['status']=='UNDECIDED' and F(t['conditional_total_area_margin'])>0
 out=R/'verify/out/n100-lower-advancement-priority.json';assert not out.exists();out.write_text(json.dumps({'schema':'n100-lower-advancement-priority/v1','target_radius':'2831/25000','common_count_bridge_recomputed':True,'remaining_B':target['m100_surviving_B'],'branches':[{'B':'31','status':'fixed-row numerical prerequisites all pass at target','missing':'new same-radius wrapper and independent mathematical transfer audit; not yet integrated'},{'B':'32','status':'PENDING','missing':'low-M81 profile and catalog-free high-M supports at target'},{'B':'33','status':'PENDING','missing':'low-M, coherent-five, degree-six and three metric subbranches at target'},{'B':'34','status':'PENDING','missing':'fresh norm-cap boundary envelope, hinge allocation and three M-range rows'},{'B':'35','status':'PENDING','missing':'variance/hinge bank and residual M26 one-core-ear row at target'},{'B':'>=36','status':'old coefficients fail scalar budget at target','missing':'new local pair envelope; candidate L=.007505 trial still incomplete'}],'old_tail_fixed_coefficients_scalar_radius_threshold_interval':[str(F(lo,scale)),str(F(lo+1,scale))],'target_tail_intercept_strict_upper_for_positive_budget':str(cap),'candidate_intercept':'1501/200000','candidate_scalar_margin':t['conditional_total_area_margin'],'candidate_partial_trial':{'visited':t['visited'],'accepted':t['accepted'],'pending':t['remaining_stack_size'],'status':t['status']},'global_bound_improved':False,'bindings':{source.relative_to(R).as_posix():sha(source),trial.relative_to(R).as_posix():sha(trial),p.relative_to(R).as_posix():sha(p)},'script_sha256':sha(Path(__file__))},indent=2)+'\n',encoding='utf-8');print('PASS target priority;B31 fixed-row conditions pass;old tail scalar threshold',str(F(lo,scale)),str(F(lo+1,scale)),'target maximum L',float(cap))
if __name__=='__main__':main()
